// Global Tombstone Registry: Tracks deleted documents by unique instance ID only (never document reference numbers)
const loadInitialTombstones = () => {
  try {
    const stored = localStorage.getItem('shipz_deleted_doc_ids');
    const list = stored ? JSON.parse(stored) : [];
    // Only keep genuine unique instance IDs (e.g. qt-*, pi-*, ci-*, bl-*, pkl-*, usr-*), NEVER document numbers like QT/*, PI/*, INV/*, CI/*
    const validIds = (Array.isArray(list) ? list : []).filter(id => {
      if (!id || typeof id !== 'string') return false;
      return id.includes('-') && !id.includes('/');
    });
    // Immediately clean sanitized list back to localStorage to purge any previously stored doc numbers
    try {
      localStorage.setItem('shipz_deleted_doc_ids', JSON.stringify(validIds));
    } catch (e) {}
    return new Set(validIds);
  } catch (e) {
    return new Set();
  }
};
