  const [commercialInvoices, setCommercialInvoices] = useState(() => loadSavedState('shipz_commercial_invoices', INITIAL_COMMERCIAL_INVOICES));
  const [blRecords, setBlRecords] = useState(() => loadSavedState('shipz_bl_records', INITIAL_BL_DRAFTS));
  const [packingLists, setPackingLists] = useState(() => loadSavedState('shipz_packing_lists', INITIAL_PACKING_LISTS));
  const [preShipmentCertificates, setPreShipmentCertificates] = useState(() => loadSavedState('shipz_pre_shipment_certificates', INITIAL_PRE_SHIPMENT_CERTIFICATES));
  const [recentActivities, setRecentActivities] = useState(() => loadSavedState('shipz_recent_activities', INITIAL_RECENT_ACTIVITIES));
  const [, setActivityTicker] = useState(0);
