        timestamp: String(createdDate).includes('T') ? createdDate : `${createdDate}T10:00:00.000Z`,
        userName: createdBy,
        title: docType === 'qt' ? 'Quotation Generated' : docType === 'pi' ? 'Proforma Invoice Created' : docType === 'ci' ? 'Commercial Invoice Finalized' : docType === 'pkl' ? 'Packing List Created' : 'BL Draft Initiated',
        description: `Initial document ${docNo} created for ${doc.consignee || doc.buyerName || 'Consignee'}.`,
