  const handleExportProductsCsv = () => {
    const headers = ['product_name', 'hsn_sac', 'gst_rate', 'inventory_type', 'product_tag', 'unit', 'net_weight_kg', 'gross_weight_kg', 'dimension_m3', 'sell_price_inr', 'scheme_type', 'scheme_unit', 'scheme_percentage', 'scheme_cap_value'];
    const rows = masterProductsSettings.map(p => [`"${(p.name || p.title || '').replace(/"/g, '""')}"`, `"${p.hsn || ''}"`, p.gstRate || 18, `"${p.inventoryType || 'Finished Goods'}"`, `"${(p.productTag || '').replace(/"/g, '""')}"`, `"${p.unit || 'Box'}"`, p.netWeightKg || p.netWeight || 0, p.grossWeightKg || p.grossWeight || 0, p.dimensionM3 || p.cbm || 0, p.sellPriceInr || p.price || 0, `"${p.schemeType || 'None'}"`, `"${p.schemeUnit || 'KG'}"`, p.schemePercentage || 0, p.schemeCapValue || 0].join(','));
    const csvStr = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvStr], {
      type: 'text/csv;charset=utf-8;'
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `product_master_export_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };
  const handleExecuteCsvImport = () => {
    if (!csvFileRawText) return alert('Please select a valid CSV file to import.');
    const lines = csvFileRawText.split(/\r?\n/).filter(line => line.trim().length > 0);
    if (lines.length <= 1) return alert('CSV file is empty or missing data rows.');
    const parseCsvLine = text => {
      const result = [];
      let cur = '';
      let inQuotes = false;
      for (let i = 0; i < text.length; i++) {
        const char = text[i];
        if (char === '"') {
          inQuotes = !inQuotes;
        } else if (char === ',' && !inQuotes) {
          result.push(cur.trim().replace(/^"|"$/g, ''));
          cur = '';
        } else {
          cur += char;
        }
      }
      result.push(cur.trim().replace(/^"|"$/g, ''));
      return result;
    };
    const headers = parseCsvLine(lines[0]).map(h => h.toLowerCase().trim());
    let updatedCount = 0;
    let createdCount = 0;
    let skippedCount = 0;
    let currentMaster = [...masterProductsSettings];
    for (let i = 1; i < lines.length; i++) {
      const cols = parseCsvLine(lines[i]);
      if (cols.length < 2) continue;
      const rowObj = {};
      headers.forEach((h, idx) => {
        rowObj[h] = cols[idx] || '';
      });
      const pName = rowObj.product_name || rowObj.name || cols[0];
      const pHsn = rowObj.hsn_sac || rowObj.hsn || cols[1];
      if (!pName || !pHsn) continue;
      const newProd = {
        id: `PROD-CSV-${Math.floor(1000 + Math.random() * 9000)}`,
        name: pName,
        sku: rowObj.sku || `SKU-${pHsn}`,
        hsn: pHsn,
        gstRate: rowObj.gst_rate || '18',
        imgUrl: rowObj.image_url || '',
        description: rowObj.product_description || '',
        inventoryType: rowObj.inventory_type || 'Finished Goods',
        productTag: rowObj.product_tag || '',
        unit: rowObj.unit || 'Box',
        netWeightKg: parseFloat(rowObj.net_weight_kg) || 0,
        grossWeightKg: parseFloat(rowObj.gross_weight_kg) || 0,
        dimensionM3: parseFloat(rowObj.dimension_m3) || 0,
        sellPriceInr: parseFloat(rowObj.sell_price_inr) || 0,
        schemeType: rowObj.scheme_type || 'RoDTEP',
        schemeUnit: rowObj.scheme_unit || 'KG',
        schemePercentage: parseFloat(rowObj.scheme_percentage) || 0,
        schemeCapValue: parseFloat(rowObj.scheme_cap_value) || 0,
        status: 'Active'
      };
      const existingIdx = currentMaster.findIndex(m => (m.name || '').toLowerCase() === pName.toLowerCase() || m.hsn === pHsn);
      if (existingIdx >= 0) {
        if (csvConflictStrategy === 'update') {
          currentMaster[existingIdx] = {
            ...currentMaster[existingIdx],
            ...newProd,
            id: currentMaster[existingIdx].id
          };
          updatedCount++;
        } else if (csvConflictStrategy === 'skip') {
          skippedCount++;
        } else if (csvConflictStrategy === 'variant') {
          newProd.name = `${newProd.name} (Variant)`;
          currentMaster.unshift(newProd);
          createdCount++;
        }
      } else {
        currentMaster.unshift(newProd);
        createdCount++;
      }
    }
    setMasterProductsSettings(currentMaster);
    setMasterProducts(currentMaster);

    // Real-time Event Dispatch
    window.dispatchEvent(new CustomEvent('shipz_products_updated', {
      detail: currentMaster
    }));
    setIsCsvImportModalOpen(false);
    setCsvFileRawText('');
    setCsvFileName('');
    setToastNotice(`CSV Sync Complete! Created: ${createdCount}, Updated: ${updatedCount}, Skipped: ${skippedCount}`);
    setTimeout(() => setToastNotice(null), 4000);
  };

