        publicId: publicId || `mglobal_erp_uploads/${cleanName}`,
        cloudinarySynced: isRealCloudinarySync,
        uploadDate: new Date().toISOString().replace('T', ' ').substring(0, 16),
        fileSizeMb: (file.size / (1024 * 1024)).toFixed(2)
