  // Real-time Line Item Calculations Engine
  const handleLineItemUpdate = (idx, field, value) => {
    const updated = [...qtFormData.lineItems];
    const item = {
      ...updated[idx],
      [field]: value
    };
    if (field === 'product') {
      const prdMaster = masterProducts.find(p => p.name === value);
      if (prdMaster) {
        item.productDescription = prdMaster.desc;
        item.unit = prdMaster.unit;
        item.price = prdMaster.price;
        const pkgCap = prdMaster.pkgCap || 20;
        const qty = item.quantity || 10;
        const netWt = (qty * prdMaster.unitNetWt).toFixed(3);
        const pkgs = (qty / pkgCap).toFixed(2);
        const grossWt = (parseFloat(netWt) + parseFloat(pkgs) * prdMaster.tareWt).toFixed(3);
        item.netWeight = netWt;
        item.totalPackages = pkgs;
        item.grossWeight = grossWt;
        item.packageText = `${pkgCap}.000`;
      }
    }
    if (field === 'quantity' || field === 'price' || field === 'packageText') {
      const qty = field === 'quantity' ? parseFloat(value) || 0 : parseFloat(item.quantity) || 0;
      const prdMaster = masterProducts.find(p => p.name === item.product);
      const pkgCap = prdMaster ? prdMaster.pkgCap : 20;
      const tareWt = prdMaster ? prdMaster.tareWt : 1.5;
      const unitNetWt = prdMaster ? prdMaster.unitNetWt : 1.0;
      const netWt = (qty * unitNetWt).toFixed(3);
      const pkgs = (pkgCap > 0 ? qty / pkgCap : 0).toFixed(2);
      const grossWt = (parseFloat(netWt) + parseFloat(pkgs) * tareWt).toFixed(3);
      item.netWeight = netWt;
      item.totalPackages = pkgs;
      item.grossWeight = grossWt;
    }
    updated[idx] = item;
    setQtFormData(prev => ({
      ...prev,
      lineItems: updated
    }));
  };

